-- Blood DK940/3 guard-clear must be relative to the dying guard,not its killer.
-- Preserve negative alive-neighbour100yd check,exact native scenario step and guide/key/door sequence.
SET @blood_guard_saved_concat=@@SESSION.group_concat_max_len;
SET SESSION group_concat_max_len=GREATEST(@@SESSION.group_concat_max_len,1048576);
START TRANSACTION;
